import { formatIssue, formatSummary, isFailure, isWarning } from './helpers'
import Formatter, { IFormatterOptions } from './'
import { doesHaveValue } from '../value_checker'
import * as messages from '@cucumber/messages'
import { ITestCaseAttempt } from './helpers/event_data_collector'
import { formatUndefinedParameterTypes } from './helpers/issue_helpers'
import { durationBetweenTimestamps } from '../time'

interface ILogIssuesRequest {
  issues: ITestCaseAttempt[]
  title: string
}

export default class SummaryFormatter extends Formatter {
  public static readonly documentation: string =
    'Summary output of feature and scenarios'

  constructor(options: IFormatterOptions) {
    super(options)
    let testRunStartedTimestamp: messages.Timestamp
    options.eventBroadcaster.on('envelope', (envelope: messages.Envelope) => {
      if (doesHaveValue(envelope.testRunStarted)) {
        testRunStartedTimestamp = envelope.testRunStarted.timestamp
      }
      if (doesHaveValue(envelope.testRunFinished)) {
        const testRunFinishedTimestamp = envelope.testRunFinished.timestamp
        this.logSummary(
          durationBetweenTimestamps(
            testRunStartedTimestamp,
            testRunFinishedTimestamp
          )
        )
      }
    })
  }

  logSummary(testRunDuration: messages.Duration): void {
    const failures: ITestCaseAttempt[] = []
    const warnings: ITestCaseAttempt[] = []
    const testCaseAttempts = this.eventDataCollector.getTestCaseAttempts()
    testCaseAttempts.forEach((testCaseAttempt) => {
      if (
        isFailure(
          testCaseAttempt.worstTestStepResult,
          testCaseAttempt.willBeRetried
        )
      ) {
        failures.push(testCaseAttempt)
      } else if (
        isWarning(
          testCaseAttempt.worstTestStepResult,
          testCaseAttempt.willBeRetried
        )
      ) {
        warnings.push(testCaseAttempt)
      }
    })
    if (this.eventDataCollector.undefinedParameterTypes.length > 0) {
      this.log(
        formatUndefinedParameterTypes(
          this.eventDataCollector.undefinedParameterTypes
        )
      )
    }
    if (failures.length > 0) {
      this.logIssues({ issues: failures, title: 'Failures' })
    }
    if (warnings.length > 0) {
      this.logIssues({ issues: warnings, title: 'Warnings' })
    }
    this.log(
      formatSummary({
        colorFns: this.colorFns,
        testCaseAttempts,
        testRunDuration,
      })
    )
  }

  logIssues({ issues, title }: ILogIssuesRequest): void {
    this.log(`${title}:\n\n`)
    issues.forEach((testCaseAttempt, index) => {
      this.log(
        formatIssue({
          colorFns: this.colorFns,
          number: index + 1,
          snippetBuilder: this.snippetBuilder,
          supportCodeLibrary: this.supportCodeLibrary,
          testCaseAttempt,
          printAttachments: this.printAttachments,
        })
      )
    })
  }
}

import Formatter, { IFormatterOptions } from './'
import { getGherkinScenarioLocationMap } from './helpers/gherkin_document_parser'
import {
  doesHaveValue,
  doesNotHaveValue,
  valueOrDefault,
} from '../value_checker'
import * as messages from '@cucumber/messages'

const DEFAULT_SEPARATOR = '\n'

interface UriToLinesMap {
  [uri: string]: number[]
}

function isFailedAttempt(worstTestStepResult: messages.TestStepResult) {
  return worstTestStepResult.status !== messages.TestStepResultStatus.PASSED
}

export default class RerunFormatter extends Formatter {
  protected readonly separator: string
  public static readonly documentation: string =
    'Prints failing files with line numbers.'

  constructor(options: IFormatterOptions) {
    super(options)
    options.eventBroadcaster.on('envelope', (envelope: messages.Envelope) => {
      if (doesHaveValue(envelope.testRunFinished)) {
        this.logFailedTestCases()
      }
    })
    const rerunOptions = valueOrDefault(options.parsedArgvOptions.rerun, {})
    this.separator = valueOrDefault(rerunOptions.separator, DEFAULT_SEPARATOR)
  }

  getFailureMap(): UriToLinesMap {
    const mapping: UriToLinesMap = {}
    this.eventDataCollector
      .getTestCaseAttempts()
      .forEach(
        ({ gherkinDocument, pickle, worstTestStepResult, willBeRetried }) => {
          if (isFailedAttempt(worstTestStepResult) && !willBeRetried) {
            const relativeUri = pickle.uri
            const line =
              getGherkinScenarioLocationMap(gherkinDocument)[
                pickle.astNodeIds[pickle.astNodeIds.length - 1]
              ].line
            if (doesNotHaveValue(mapping[relativeUri])) {
              mapping[relativeUri] = []
            }
            mapping[relativeUri].push(line)
          }
        }
      )

    return mapping
  }

  formatFailedTestCases(): string {
    const mapping = this.getFailureMap()

    return Object.keys(mapping)
      .map((uri) => {
        const lines = mapping[uri]
        return `${uri}:${lines.join(':')}`
      })
      .join(this.separator)
  }

  logFailedTestCases(): void {
    const failedTestCases = this.formatFailedTestCases()
    this.log(failedTestCases)
  }
}

