      .filter((attempt) => !attempt.willBeRetried)
  }

  private getTestSteps(
    testCaseAttempt: ITestCaseAttempt,
    gherkinStepMap: Record<string, messages.Step>,
    pickleStepMap: Record<string, messages.PickleStep>
  ) {
    return testCaseAttempt.testCase.testSteps.map((testStep) => {
      const isBeforeHook = !doesHaveValue(testStep.pickleStepId)
      return this.getTestStep({
        isBeforeHook,
        gherkinStepMap,
        pickleStepMap,
        testStep,
        testStepAttachments: testCaseAttempt.stepAttachments[testStep.id],
        testStepResult: testCaseAttempt.stepResults[testStep.id],
      })
    })
  }

  private getTestStep({
    isBeforeHook,
    gherkinStepMap,
    pickleStepMap,
    testStep,
    testStepAttachments,
    testStepResult,
  }: IBuildJUnitTestStepOptions): IJUnitTestStep {
    const data: Partial<IJUnitTestStep> = {}
    if (testStep.pickleStepId) {
      const pickleStep = pickleStepMap[testStep.pickleStepId]
      data.keyword = getStepKeyword({ pickleStep, gherkinStepMap })
      data.line = gherkinStepMap[pickleStep.astNodeIds[0]].location.line
      data.name = pickleStep.text
    } else {
      data.keyword = isBeforeHook ? 'Before' : 'After'
      data.hidden = true
    }
    data.result = testStepResult
    data.time = testStepResult.duration
      ? this.durationToSeconds(testStepResult.duration)
      : 0
    data.attachments = testStepAttachments
    return data as IJUnitTestStep
  }

  private getTestCaseResult(steps: IJUnitTestStep[]): IJUnitTestCaseResult {
    const { status, message, exception } = getWorstTestStepResult(
      steps.map((step) => step.result)
    )
    return {
      status,
      failure:
        message || exception
          ? {
              type: exception?.type,
              message: exception?.message,
              detail: message,
            }
          : undefined,
    }
  }

  private durationToSeconds(duration: Duration): number {
    const NANOS_IN_SECOND = 1_000_000_000
    return (
      (duration.seconds * NANOS_IN_SECOND + duration.nanos) / NANOS_IN_SECOND
    )
  }

  private nameOrDefault(name: string, fallbackSuffix: string): string {
    if (!name) {
      return `(unnamed ${fallbackSuffix})`
    }
    return name
  }

  private getTestCaseName(
    feature: Feature,
    rule: Rule | undefined,
    pickle: Pickle
  ) {
    const featureName = this.nameOrDefault(feature.name, 'feature')
    const pickleName = this.nameOrDefault(pickle.name, 'scenario')
    const testCaseName = rule
      ? this.nameOrDefault(rule.name, 'rule') + ': ' + pickleName
      : pickleName
    if (!this.names[featureName]) {
      this.names[featureName] = []
    }
    let index = 0
    while (
      this.names[featureName].includes(
        index > 0 ? `${testCaseName} [${index}]` : testCaseName
      )
    ) {
      index++
    }
    const name = index > 0 ? `${testCaseName} [${index}]` : testCaseName
    this.names[featureName].push(name)
    return name
  }

  private formatTestSteps(steps: IJUnitTestStep[]): string {
    return steps
      .filter((step) => !step.hidden)
      .map((step) => {
        const statusText = step.result.status.toLowerCase()
        const maxLength = 80 - statusText.length - 3
        const stepText = `${step.keyword}${step.name}`
          .padEnd(maxLength, '.')
          .substring(0, maxLength)
        return `${stepText}...${statusText}`
      })
      .join('\n')
  }

  private onTestRunFinished(): void {
    const testCases = this.getTestCases()

    const tests = testCases.map<IJUnitTestCase>(
      (testCaseAttempt: ITestCaseAttempt) => {
        const { gherkinDocument, pickle } = testCaseAttempt
        const { feature } = gherkinDocument
        const gherkinExampleRuleMap = getGherkinExampleRuleMap(gherkinDocument)
        const rule = gherkinExampleRuleMap[pickle.astNodeIds[0]]
        const gherkinStepMap = getGherkinStepMap(gherkinDocument)
        const pickleStepMap = getPickleStepMap(pickle)

        const steps = this.getTestSteps(
          testCaseAttempt,
          gherkinStepMap,
          pickleStepMap
        )
        const stepDuration = steps.reduce(
          (total, step) => total + (step.time || 0),
          0
        )

        return {
          classname: this.nameOrDefault(feature.name, 'feature'),
          name: this.getTestCaseName(feature, rule, pickle),
          time: stepDuration,
          result: this.getTestCaseResult(steps),
          systemOutput: this.formatTestSteps(steps),
          steps,
        }
      }
    )

    const passed = tests.filter(
      (item) => item.result.status === TestStepResultStatus.PASSED
    ).length
    const skipped = tests.filter(
      (item) => item.result.status === TestStepResultStatus.SKIPPED
    ).length
    const failures = tests.length - passed - skipped

    const testSuite: IJUnitTestSuite = {
      name: this.suiteName,
      tests,
      failures,
      skipped,
      time: tests.reduce((total, test) => total + test.time, 0),
    }

    this.log(this.buildXmlReport(testSuite))
  }

  private buildXmlReport(testSuite: IJUnitTestSuite): string {
    const xmlReport = xmlbuilder
      .create('testsuite', { invalidCharReplacement: '' })
      .att('failures', testSuite.failures)
      .att('skipped', testSuite.skipped)
      .att('name', testSuite.name)
      .att('time', testSuite.time)
      .att('tests', testSuite.tests.length)
    testSuite.tests.forEach((test) => {
      const xmlTestCase = xmlReport.ele('testcase', {
        classname: test.classname,
        name: test.name,
        time: test.time,
      })
      if (test.result.status === TestStepResultStatus.SKIPPED) {
        xmlTestCase.ele('skipped')
      } else if (test.result.status !== TestStepResultStatus.PASSED) {
        const xmlFailure = xmlTestCase.ele('failure', {
          type: test.result.failure?.type,
          message: test.result.failure?.message,
        })
        if (test.result?.failure) {
          xmlFailure.cdata(test.result.failure.detail)
        }
      }
      xmlTestCase.ele('system-out', {}).cdata(test.systemOutput)
    })

    return xmlReport.end({ pretty: true })
  }
}

import stringArgv from 'string-argv'
import fs from 'fs'
import path from 'path'
import YAML from 'yaml'
import { promisify } from 'util'
import { pathToFileURL } from 'url'
import { IConfiguration } from './types'
import { mergeConfigurations } from './merge_configurations'
import ArgvParser from './argv_parser'
import { checkSchema } from './check_schema'
import { ILogger } from '../logger'

// eslint-disable-next-line @typescript-eslint/no-var-requires
const { importer } = require('../importer')

export async function fromFile(
  logger: ILogger,
  cwd: string,
  file: string,
  profiles: string[] = []
): Promise<Partial<IConfiguration>> {
  const definitions = await loadFile(cwd, file)
  if (!definitions.default) {
    logger.debug('No default profile defined in configuration file')
    definitions.default = {}
  }
  if (profiles.length < 1) {
    logger.debug('No profiles specified; using default profile')
    profiles = ['default']
  }
  const definedKeys = Object.keys(definitions)
  profiles.forEach((profileKey) => {
    if (!definedKeys.includes(profileKey)) {
      throw new Error(`Requested profile "${profileKey}" doesn't exist`)
    }
  })
  return mergeConfigurations(
    {},
    ...profiles.map((profileKey) =>
      extractConfiguration(logger, profileKey, definitions[profileKey])
    )
  )
}

async function loadFile(
  cwd: string,
  file: string
): Promise<Record<string, any>> {
  const filePath: string = path.join(cwd, file)
  const extension = path.extname(filePath)
  let definitions
  switch (extension) {
    case '.json':
      definitions = JSON.parse(
        await promisify(fs.readFile)(filePath, { encoding: 'utf-8' })
      )
      break
    case '.yaml':
    case '.yml':
      definitions = YAML.parse(
        await promisify(fs.readFile)(filePath, { encoding: 'utf-8' })
      )
      break
    default:
      try {
        // eslint-disable-next-line @typescript-eslint/no-var-requires
        definitions = require(filePath)
      } catch (error) {
        if (error.code === 'ERR_REQUIRE_ESM') {
          definitions = await importer(pathToFileURL(filePath))
        } else {
          throw error
        }
      }
  }
  if (typeof definitions !== 'object') {
    throw new Error(`Configuration file ${filePath} does not export an object`)
  }
  return definitions
}

function extractConfiguration(
  logger: ILogger,
  name: string,
  definition: any
): Partial<IConfiguration> {
  if (typeof definition === 'string') {
    logger.debug(`Profile "${name}" value is a string; parsing as argv`)
    const { configuration } = ArgvParser.parse([
      'node',
      'cucumber-js',
      ...stringArgv(definition),
    ])
    return configuration
  }
  try {
    return checkSchema(definition)
  } catch (error) {
    throw new Error(
      `Requested profile "${name}" failed schema validation: ${error.errors.join(
        ' '
      )}`
    )
  }
}

import { IConfiguration } from './types'
import mergeWith from 'lodash.mergewith'

const ADDITIVE_ARRAYS = [
  'format',
  'import',
  'name',
  'paths',
  'require',
  'requireModule',
]
const TAG_EXPRESSIONS = ['tags', 'retryTagFilter']

function mergeArrays(objValue: any[], srcValue: any[]) {
  if (objValue && srcValue) {
    return [].concat(objValue, srcValue)
  }
  return undefined
}

function mergeTagExpressions(objValue: string, srcValue: string) {
  if (objValue && srcValue) {
    return `${wrapTagExpression(objValue)} and ${wrapTagExpression(srcValue)}`
  }
  return undefined
}

function wrapTagExpression(raw: string) {
  if (raw.startsWith('(') && raw.endsWith(')')) {
    return raw
  }
  return `(${raw})`
}

function customizer(objValue: any, srcValue: any, key: string): any {
  if (ADDITIVE_ARRAYS.includes(key)) {
    return mergeArrays(objValue, srcValue)
  }
  if (TAG_EXPRESSIONS.includes(key)) {
    return mergeTagExpressions(objValue, srcValue)
  }
  return undefined
}

export function mergeConfigurations<T = Partial<IConfiguration>>(
  source: T,
  ...configurations: Partial<IConfiguration>[]
): T {
  return mergeWith({}, source, ...configurations, customizer)
}

export function isTruthyString(s: string | undefined): boolean {
  if (s === undefined) {
    return false
  }
  return s.match(/^(false|no|0)$/i) === null
}

import { ILogger } from '../logger'

export function splitFormatDescriptor(
  logger: ILogger,
  option: string
): string[] {
  const doWarning = (result: string[]) => {
    let expected = `"${result[0]}"`
    if (result[1]) {
      expected += `:"${result[1]}"`
    }
    logger.warn(
      `Each part of a user-specified format should be quoted; see https://github.com/cucumber/cucumber-js/blob/main/docs/deprecations.md#ambiguous-colons-in-formats
Change to ${expected}`
    )
  }
  let result: string[]
  let match1, match2

  // "foo":"bar" or "foo":bar
  if ((match1 = option.match(/^"([^"]*)":(.*)$/)) !== null) {
    // "foo":"bar"
    if ((match2 = match1[2].match(/^"([^"]*)"$/)) !== null) {
      result = [match1[1], match2[1]]
    }
    // "foo":bar
    else {
      result = [match1[1], match1[2]]
      if (result[1].includes(':')) {
        doWarning(result)
      }
    }
  }
  // foo:"bar"
  else if ((match1 = option.match(/^(.*):"([^"]*)"$/)) !== null) {
    result = [match1[1], match1[2]]
    if (result[0].includes(':')) {
      doWarning(result)
    }
  }
  // "foo"
  else if ((match1 = option.match(/^"([^"]*)"$/)) !== null) {
    result = [match1[1], '']
  }
  // file://foo or file:///foo or file://C:/foo or file://C:\foo or file:///C:/foo or file:///C:\foo
  else if (
    (match1 = option.match(/^(file:\/{2,3}(?:[a-zA-Z]:[/\\])?)(.*)$/)) !== null
  ) {
    // file://foo:bar
    if ((match2 = match1[2].match(/^([^:]*):(.*)$/)) !== null) {
      result = [match1[1] + match2[1], match2[2]]
    } else {
      result = [option, '']
    }
    doWarning(result)
  }
  // C:\foo or C:/foo
  else if ((match1 = option.match(/^([a-zA-Z]:[/\\])(.*)$/)) !== null) {
    // C:\foo:bar or C:/foo:bar
    if ((match2 = match1[2].match(/^([^:]*):(.*)$/)) !== null) {
      result = [match1[1] + match2[1], match2[2]]
    } else {
      result = [option, '']
    }
    doWarning(result)
  }
  // foo:bar
  else if ((match1 = option.match(/^([^:]*):(.*)$/)) !== null) {
    result = [match1[1], match1[2]]
    if (option.split(':').length > 2) {
      doWarning(result)
    }
  }
  // foo
  else {
    result = [option, '']
  }

  return result
}

import {
  IRunEnvironment,
  IResolvedConfiguration,
  ILoadConfigurationOptions,
} from './types'
import { locateFile } from '../configuration/locate_file'
import {
  DEFAULT_CONFIGURATION,
  fromFile,
  mergeConfigurations,
} from '../configuration'
import { validateConfiguration } from '../configuration/validate_configuration'
import { convertConfiguration } from './convert_configuration'
import { mergeEnvironment } from './environment'
import { ILogger } from '../logger'
import { ConsoleLogger } from './console_logger'

/**
 * Load user-authored configuration to be used in a test run.
 *
 * @public
 * @param options - Coordinates required to find configuration.
 * @param environment - Project environment.
 */
export async function loadConfiguration(
  options: ILoadConfigurationOptions = {},
  environment: IRunEnvironment = {}
): Promise<IResolvedConfiguration> {
  const { cwd, stderr, env, debug } = mergeEnvironment(environment)
  const logger: ILogger = new ConsoleLogger(stderr, debug)
  const configFile = options.file ?? locateFile(cwd)
  if (configFile) {
    logger.debug(`Configuration will be loaded from "${configFile}"`)
  } else {
    logger.debug('No configuration file found')
  }
  const profileConfiguration = configFile
    ? await fromFile(logger, cwd, configFile, options.profiles)
    : {}
  const original = mergeConfigurations(
    DEFAULT_CONFIGURATION,
    profileConfiguration,
    options.provided
  )
  logger.debug('Resolved configuration:', original)
  validateConfiguration(original, logger)
  const runnable = await convertConfiguration(logger, original, env)
  return {
    useConfiguration: original,
    runConfiguration: runnable,
  }
}

import { IConfiguration } from './types'
import { ILogger } from '../logger'

export function validateConfiguration(
  configuration: IConfiguration,
  logger: ILogger
): void {
  if (configuration.publishQuiet) {
    logger.warn(
      '`publishQuiet` option is no longer needed, you can remove it from your configuration; see https://github.com/cucumber/cucumber-js/blob/main/docs/deprecations.md'
    )
  }
  if (configuration.retryTagFilter && !configuration.retry) {
    throw new Error(
      'a positive `retry` count must be specified when setting `retryTagFilter`'
    )
  }
}

import {
  IConfiguration,
  isTruthyString,
  splitFormatDescriptor,
} from '../configuration'
import { IPublishConfig } from '../formatter'
import { IRunConfiguration } from './types'
import { ILogger } from '../logger'

export async function convertConfiguration(
  logger: ILogger,
  flatConfiguration: IConfiguration,
  env: NodeJS.ProcessEnv
): Promise<IRunConfiguration> {
  return {
    sources: {
      paths: flatConfiguration.paths,
      defaultDialect: flatConfiguration.language,
      names: flatConfiguration.name,
      tagExpression: flatConfiguration.tags,
      order: flatConfiguration.order,
    },
    support: {
      requireModules: flatConfiguration.requireModule,
      requirePaths: flatConfiguration.require,
      importPaths: flatConfiguration.import,
    },
    runtime: {
      dryRun: flatConfiguration.dryRun,
      failFast: flatConfiguration.failFast,
      filterStacktraces: !flatConfiguration.backtrace,
      parallel: flatConfiguration.parallel,
      retry: flatConfiguration.retry,
      retryTagFilter: flatConfiguration.retryTagFilter,
      strict: flatConfiguration.strict,
      worldParameters: flatConfiguration.worldParameters,
    },
    formats: convertFormats(logger, flatConfiguration, env),
  }
}

function convertFormats(
  logger: ILogger,
  flatConfiguration: IConfiguration,
  env: NodeJS.ProcessEnv
) {
  const splitFormats: string[][] = flatConfiguration.format.map((item) =>
    Array.isArray(item) ? item : splitFormatDescriptor(logger, item)
  )
  return {
    stdout:
      [...splitFormats].reverse().find(([, target]) => !target)?.[0] ??
      'progress',
    files: splitFormats
      .filter(([, target]) => !!target)
      .reduce((mapped, [type, target]) => {
        return {
          ...mapped,
          [target]: type,
        }
      }, {}),
    publish: makePublishConfig(flatConfiguration, env),
    options: flatConfiguration.formatOptions,
  }
}

function makePublishConfig(
  flatConfiguration: IConfiguration,
  env: NodeJS.ProcessEnv
): IPublishConfig | false {
  const enabled = isPublishing(flatConfiguration, env)
  if (!enabled) {
    return false
  }
  return {
    url: env.CUCUMBER_PUBLISH_URL,
    token: env.CUCUMBER_PUBLISH_TOKEN,
  }
}

function isPublishing(
  flatConfiguration: IConfiguration,
  env: NodeJS.ProcessEnv
): boolean {
  return (
    flatConfiguration.publish ||
    isTruthyString(env.CUCUMBER_PUBLISH_ENABLED) ||
    env.CUCUMBER_PUBLISH_TOKEN !== undefined
  )
}

import { IRunEnvironment } from './types'

export function mergeEnvironment(
  provided: IRunEnvironment
): Required<IRunEnvironment> {
  return Object.assign(
    {},
    {
      cwd: process.cwd(),
      stdout: process.stdout,
      stderr: process.stderr,
      env: process.env,
      debug: false,
    },
    provided
  )
}

import { Console } from 'console'
import { Writable } from 'stream'
import { ILogger } from '../logger'

export class ConsoleLogger implements ILogger {
  private console: Console = new Console(this.stream)
  constructor(private stream: Writable, private debugEnabled: boolean) {}

  debug(...content: any[]): void {
    if (this.debugEnabled) {
      this.console.debug(...content)
    }
  }

  error(...content: any[]): void {
    this.console.error(...content)
  }

  warn(...content: any[]): void {
    this.console.warn(...content)
  }
}

import {
  ILoadSourcesResult,
  IPlannedPickle,
  IRunEnvironment,
  ISourcesCoordinates,
  ISourcesError,
} from './types'
import { resolvePaths } from './paths'
import { IdGenerator } from '@cucumber/messages'
import { mergeEnvironment } from './environment'
import { getFilteredPicklesAndErrors } from './gherkin'
import { ConsoleLogger } from './console_logger'
import { ILogger } from '../logger'

/**
 * Load and parse features, produce a filtered and ordered test plan and/or parse errors.
 *
 * @public
 * @param coordinates - Coordinates required to find features
 * @param environment - Project environment.
 */
export async function loadSources(
  coordinates: ISourcesCoordinates,
  environment: IRunEnvironment = {}
): Promise<ILoadSourcesResult> {
  const { cwd, stderr, debug } = mergeEnvironment(environment)
  const logger: ILogger = new ConsoleLogger(stderr, debug)
  const newId = IdGenerator.uuid()
  const { unexpandedFeaturePaths, featurePaths } = await resolvePaths(
    logger,
    cwd,
    coordinates
  )
  if (featurePaths.length === 0) {
    return {
      plan: [],
      errors: [],
    }
  }
  const { filteredPickles, parseErrors } = await getFilteredPicklesAndErrors({
    newId,
    cwd,
    logger,
    unexpandedFeaturePaths,
    featurePaths,
    coordinates,
  })
  const plan: IPlannedPickle[] = filteredPickles.map(
    ({ location, pickle }) => ({
      name: pickle.name,
      uri: pickle.uri,
      location,
    })
  )
  const errors: ISourcesError[] = parseErrors.map(({ source, message }) => {
    return {
      uri: source.uri,
      location: source.location,
      message,
    }
  })
  return {
    plan,
    errors,
  }
}

import { promisify } from 'util'
import glob from 'glob'
import path from 'path'
import fs from 'mz/fs'
import { ISourcesCoordinates, ISupportCodeCoordinates } from './types'
import { ILogger } from '../logger'

export async function resolvePaths(
  logger: ILogger,
  cwd: string,
  sources: Pick<ISourcesCoordinates, 'paths'>,
  support: ISupportCodeCoordinates = {
    requireModules: [],
    requirePaths: [],
    importPaths: [],
  }
): Promise<{
  unexpandedFeaturePaths: string[]
  featurePaths: string[]
  requirePaths: string[]
  importPaths: string[]
}> {
  const unexpandedFeaturePaths = await getUnexpandedFeaturePaths(
    cwd,
    sources.paths
  )
  const featurePaths: string[] = await expandFeaturePaths(
    cwd,
    unexpandedFeaturePaths
  )
  logger.debug('Found feature files based on configuration:', featurePaths)
  const { requirePaths, importPaths } = await deriveSupportPaths(
    cwd,
    featurePaths,
    support.requirePaths,
    support.importPaths
  )
  logger.debug(
    'Found support files to load via `require` based on configuration:',
    requirePaths
  )
  logger.debug(
    'Found support files to load via `import` based on configuration:',
    importPaths
  )
  return {
    unexpandedFeaturePaths,
    featurePaths,
    requirePaths,
    importPaths,
  }
}

async function expandPaths(
  cwd: string,
  unexpandedPaths: string[],
  defaultExtension: string
): Promise<string[]> {
  const expandedPaths = await Promise.all(
    unexpandedPaths.map(async (unexpandedPath) => {
      const matches = await promisify(glob)(unexpandedPath, {
        absolute: true,
        cwd,
      })
      const expanded = await Promise.all(
        matches.map(async (match) => {
          if (path.extname(match) === '') {
            return await promisify(glob)(`${match}/**/*${defaultExtension}`)
          }
          return [match]
        })
      )
      return expanded.flat()
    })
  )
  const normalized = expandedPaths.flat().map((x) => path.normalize(x))
  return [...new Set(normalized)]
}

async function getUnexpandedFeaturePaths(
  cwd: string,
  args: string[]
): Promise<string[]> {
  if (args.length > 0) {
    const nestedFeaturePaths = await Promise.all(
      args.map(async (arg) => {
        const filename = path.basename(arg)
        if (filename[0] === '@') {
          const filePath = path.join(cwd, arg)
          const content = await fs.readFile(filePath, 'utf8')
          return content.split('\n').map((x) => x.trim())
        }
        return [arg]
      })
    )
    const featurePaths = nestedFeaturePaths.flat()
    if (featurePaths.length > 0) {
      return featurePaths.filter((x) => x !== '')
    }
  }
  return ['features/**/*.{feature,feature.md}']
}

function getFeatureDirectoryPaths(
  cwd: string,
  featurePaths: string[]
): string[] {
  const featureDirs = featurePaths.map((featurePath) => {
    let featureDir = path.dirname(featurePath)
    let childDir: string
    let parentDir = featureDir
    while (childDir !== parentDir) {
      childDir = parentDir
      parentDir = path.dirname(childDir)
      if (path.basename(parentDir) === 'features') {
        featureDir = parentDir
        break
      }
    }
    return path.relative(cwd, featureDir)
  })
  return [...new Set(featureDirs)]
}

async function expandFeaturePaths(
  cwd: string,
  featurePaths: string[]
): Promise<string[]> {
  featurePaths = featurePaths.map((p) => p.replace(/(:\d+)*$/g, '')) // Strip line numbers
  return await expandPaths(cwd, featurePaths, '.feature')
}

async function deriveSupportPaths(
  cwd: string,
  featurePaths: string[],
  unexpandedRequirePaths: string[],
  unexpandedImportPaths: string[]
): Promise<{
  requirePaths: string[]
  importPaths: string[]
}> {
  if (
    unexpandedRequirePaths.length === 0 &&
    unexpandedImportPaths.length === 0
  ) {
    const defaultPaths = getFeatureDirectoryPaths(cwd, featurePaths)
    const requirePaths = await expandPaths(cwd, defaultPaths, '.js')
    const importPaths = await expandPaths(cwd, defaultPaths, '.mjs')
    return { requirePaths, importPaths }
  }
  const requirePaths =
    unexpandedRequirePaths.length > 0
      ? await expandPaths(cwd, unexpandedRequirePaths, '.js')
      : []
  const importPaths =
    unexpandedImportPaths.length > 0
      ? await expandPaths(cwd, unexpandedImportPaths, '.@(js|cjs|mjs)')
      : []
  return { requirePaths, importPaths }
}

import {
  GherkinStreams,
  IGherkinStreamOptions,
} from '@cucumber/gherkin-streams'
import {
  Envelope,
  GherkinDocument,
  IdGenerator,
  Location,
  ParseError,
  Pickle,
} from '@cucumber/messages'
import { Query as GherkinQuery } from '@cucumber/gherkin-utils'
import PickleFilter from '../pickle_filter'
import { orderPickles } from '../cli/helpers'
import { ISourcesCoordinates } from './types'
import { ILogger } from '../logger'

interface PickleWithDocument {
  gherkinDocument: GherkinDocument
  location: Location
  pickle: Pickle
}

export async function getFilteredPicklesAndErrors({
  newId,
  cwd,
  logger,
  unexpandedFeaturePaths,
  featurePaths,
  coordinates,
  onEnvelope,
}: {
  newId: IdGenerator.NewId
  cwd: string
  logger: ILogger
  unexpandedFeaturePaths: string[]
  featurePaths: string[]
  coordinates: ISourcesCoordinates
  onEnvelope?: (envelope: Envelope) => void
}): Promise<{
  filteredPickles: PickleWithDocument[]
  parseErrors: ParseError[]
}> {
  const gherkinQuery = new GherkinQuery()
  const parseErrors: ParseError[] = []
  await gherkinFromPaths(
    featurePaths,
    {
      newId,
      relativeTo: cwd,
      defaultDialect: coordinates.defaultDialect,
    },
    (envelope) => {
      gherkinQuery.update(envelope)
      if (envelope.parseError) {
        parseErrors.push(envelope.parseError)
      }
      onEnvelope?.(envelope)
    }
  )
  const pickleFilter = new PickleFilter({
    cwd,
    featurePaths: unexpandedFeaturePaths,
    names: coordinates.names,
    tagExpression: coordinates.tagExpression,
  })
  const filteredPickles: PickleWithDocument[] = gherkinQuery
    .getPickles()
    .filter((pickle) => {
      const gherkinDocument = gherkinQuery
        .getGherkinDocuments()
        .find((doc) => doc.uri === pickle.uri)
      return pickleFilter.matches({ gherkinDocument, pickle })
    })
    .map((pickle) => {
      const gherkinDocument = gherkinQuery
        .getGherkinDocuments()
        .find((doc) => doc.uri === pickle.uri)
      const location = gherkinQuery.getLocation(
        pickle.astNodeIds[pickle.astNodeIds.length - 1]
      )
      return {
        gherkinDocument,
        location,
        pickle,
      }
    })
  orderPickles(filteredPickles, coordinates.order, logger)
  return {
    filteredPickles,
    parseErrors,
  }
}

async function gherkinFromPaths(
  paths: string[],
  options: IGherkinStreamOptions,
  onEnvelope: (envelope: Envelope) => void
): Promise<void> {
  return new Promise((resolve, reject) => {
    const gherkinMessageStream = GherkinStreams.fromPaths(paths, options)
    gherkinMessageStream.on('data', onEnvelope)
    gherkinMessageStream.on('end', resolve)
    gherkinMessageStream.on('error', reject)
  })
}

import * as messages from '@cucumber/messages'
import { GherkinDocumentHandlers } from './GherkinDocumentHandlers'

/**
 * Walks a Gherkin Document, visiting each node depth first (in the order they appear in the source)
 *
 * @param gherkinDocument
 * @param initialValue the initial value of the traversal
 * @param handlers handlers for each node type, which may return a new value
 * @return result the final value
 */
export function walkGherkinDocument<Acc>(
  gherkinDocument: messages.GherkinDocument,
  initialValue: Acc,
  handlers: Partial<GherkinDocumentHandlers<Acc>>
): Acc {
  let acc = initialValue
  const h: GherkinDocumentHandlers<Acc> = { ...makeDefaultHandlers<Acc>(), ...handlers }
  const feature = gherkinDocument.feature
  if (!feature) return acc
  acc = walkTags(feature.tags || [], acc)
  acc = h.feature(feature, acc)

  for (const child of feature.children) {
    if (child.background) {
      acc = walkStepContainer(child.background, acc)
    } else if (child.scenario) {
      acc = walkStepContainer(child.scenario, acc)
    } else if (child.rule) {
      acc = walkTags(child.rule.tags || [], acc)
      acc = h.rule(child.rule, acc)
      for (const ruleChild of child.rule.children) {
        if (ruleChild.background) {
          acc = walkStepContainer(ruleChild.background, acc)
        } else if (ruleChild.scenario) {
          acc = walkStepContainer(ruleChild.scenario, acc)
        }
      }
    }
  }
  return acc

  function walkTags(tags: readonly messages.Tag[], acc: Acc): Acc {
    return tags.reduce((acc, tag) => h.tag(tag, acc), acc)
  }

  function walkSteps(steps: readonly messages.Step[], acc: Acc): Acc {
    return steps.reduce((acc, step) => walkStep(step, acc), acc)
  }

  function walkStep(step: messages.Step, acc: Acc): Acc {
    acc = h.step(step, acc)
    if (step.docString) {
      acc = h.docString(step.docString, acc)
    }
    if (step.dataTable) {
      acc = h.dataTable(step.dataTable, acc)
      acc = walkTableRows(step.dataTable.rows, acc)
    }
    return acc
  }

  function walkTableRows(tableRows: readonly messages.TableRow[], acc: Acc): Acc {
    return tableRows.reduce((acc, tableRow) => walkTableRow(tableRow, acc), acc)
  }

  function walkTableRow(tableRow: messages.TableRow, acc: Acc): Acc {
    acc = h.tableRow(tableRow, acc)
    return tableRow.cells.reduce((acc, tableCell) => h.tableCell(tableCell, acc), acc)
  }

  function walkStepContainer(
    stepContainer: messages.Scenario | messages.Background,
    acc: Acc
  ): Acc {
    const scenario: messages.Scenario = 'tags' in stepContainer ? stepContainer : null
    acc = walkTags(scenario?.tags || [], acc)
    acc = scenario
      ? h.scenario(scenario, acc)
      : h.background(stepContainer as messages.Background, acc)
    acc = walkSteps(stepContainer.steps, acc)

    if (scenario) {
      for (const examples of scenario.examples || []) {
        acc = walkTags(examples.tags || [], acc)
        acc = h.examples(examples, acc)
        if (examples.tableHeader) {
          acc = walkTableRow(examples.tableHeader, acc)
          acc = walkTableRows(examples.tableBody || [], acc)
        }
      }
    }
    return acc
  }
}

function makeDefaultHandlers<Acc>() {
  const defaultHandlers: GherkinDocumentHandlers<Acc> = {
    feature(feature, acc) {
      return acc
    },
    background(background, acc) {
      return acc
    },
    rule(rule, acc) {
      return acc
    },
    scenario(scenario, acc) {
      return acc
    },
    step(step, acc) {
      return acc
    },
    examples(examples, acc) {
      return acc
    },
    tag(tag, acc) {
      return acc
    },
    comment(comment, acc) {
      return acc
    },
    dataTable(dataTable, acc) {
      return acc
    },
    tableRow(tableRow, acc) {
      return acc
    },
    tableCell(tableCell, acc) {
      return acc
    },
    docString(docString, acc) {
      return acc
    },
  }
  return defaultHandlers
}

import * as messages from '@cucumber/messages'
import { walkGherkinDocument } from './walkGherkinDocument'

export type Syntax = 'markdown' | 'gherkin'

export default function pretty(
  gherkinDocument: messages.GherkinDocument,
  syntax: Syntax = 'gherkin'
): string {
  let scenarioLevel = 1
  return walkGherkinDocument<string>(gherkinDocument, '', {
    feature(feature, content) {
      return content
        .concat(prettyLanguageHeader(feature.language))
        .concat(prettyKeywordContainer(feature, syntax, 0))
    },
    rule(rule, content) {
      scenarioLevel = 2
      return content.concat(prettyKeywordContainer(rule, syntax, 1))
    },
    background(background, content) {
      return content.concat(prettyKeywordContainer(background, syntax, scenarioLevel))
    },
    scenario(scenario, content) {
      return content.concat(prettyKeywordContainer(scenario, syntax, scenarioLevel))
    },
    examples(examples, content) {
      const tableRows = examples.tableHeader ? [examples.tableHeader, ...examples.tableBody] : []
      return content
        .concat(prettyKeywordContainer(examples, syntax, scenarioLevel + 1))
        .concat(prettyTableRows(tableRows, syntax, scenarioLevel + 2))
    },
    step(step, content) {
      return content
        .concat(stepPrefix(scenarioLevel + 1, syntax))
        .concat(step.keyword)
        .concat(step.text)
        .concat('\n')
    },
    dataTable(dataTable, content) {
      const level = syntax === 'markdown' ? 1 : scenarioLevel + 2
      return content.concat(prettyTableRows(dataTable.rows || [], syntax, level))
    },
    docString(docString, content) {
      const delimiter = makeDocStringDelimiter(syntax, docString)
      const level = syntax === 'markdown' ? 1 : scenarioLevel + 2
      const indent = spaces(level)
      let docStringContent = docString.content.replace(/^/gm, indent)
      if (syntax === 'gherkin') {
        if (docString.delimiter === '"""') {
          docStringContent = docStringContent.replace(/"""/gm, '\\"\\"\\"')
        } else {
          docStringContent = docStringContent.replace(/```/gm, '\\`\\`\\`')
        }
      }
      return content
        .concat(indent)
        .concat(delimiter)
        .concat(docString.mediaType || '')
        .concat('\n')
        .concat(docStringContent)
        .concat('\n')
        .concat(indent)
        .concat(delimiter)
        .concat('\n')
    },
  })
}

function prettyLanguageHeader(language: string | undefined): string {
  return language === 'en' ? '' : `# language: ${language}\n`
}

function prettyKeywordContainer(
  stepContainer:
    | messages.Feature
    | messages.Scenario
    | messages.Rule
    | messages.Examples
    | messages.Background,
  syntax: Syntax,
  level: number
): string {
  const tags: readonly messages.Tag[] = 'tags' in stepContainer ? stepContainer.tags : []
  const stepCount = 'steps' in stepContainer ? stepContainer.steps.length : 0
  const description = prettyDescription(stepContainer.description, syntax)

  return ''
    .concat(level === 0 ? '' : '\n')
    .concat(prettyTags(tags, syntax, level))
    .concat(keywordPrefix(level, syntax))
    .concat(stepContainer.keyword)
    .concat(': ')
    .concat(stepContainer.name)
    .concat('\n')
    .concat(description)
    .concat(description && stepCount > 0 ? '\n' : '')
}

function prettyDescription(description: string, syntax: Syntax): string {
  if (!description) return ''
  if (syntax === 'gherkin') return description + '\n'
  else return description.replace(/^\s*/gm, '') + '\n'
}

function prettyTags(tags: readonly messages.Tag[], syntax: Syntax, level: number): string {
  if (tags === undefined || tags.length == 0) {
    return ''
  }
  const prefix = syntax === 'gherkin' ? spaces(level) : ''
  const tagQuote = syntax === 'gherkin' ? '' : '`'
  return prefix + tags.map((tag) => `${tagQuote}${tag.name}${tagQuote}`).join(' ') + '\n'
}

function keywordPrefix(level: number, syntax: Syntax): string {
  if (syntax === 'markdown') {
    return new Array(level + 2).join('#') + ' '
  } else {
    return spaces(level)
  }
}

function stepPrefix(level: number, syntax: Syntax): string {
  if (syntax === 'markdown') {
    return '* '
  } else {
    return new Array(level + 1).join('  ')
  }
}

function spaces(level: number): string {
  return new Array(level + 1).join('  ')
}

function makeDocStringDelimiter(syntax: Syntax, docString: messages.DocString) {
  if (syntax === 'gherkin') {
    return docString.delimiter.substring(0, 3)
  }

  // The length of the fenced code block delimiter is three backticks when the content inside doesn't have backticks.
  // If the content inside has three or more backticks, the number of backticks in the delimiter must be at least one more
  // https://github.github.com/gfm/#fenced-code-blocks
  const threeOrMoreBackticks = /(```+)/g
  let maxContentBackTickCount = 2
  let match
  do {
    match = threeOrMoreBackticks.exec(docString.content)
    if (match) {
      maxContentBackTickCount = Math.max(maxContentBackTickCount, match[1].length)
    }
  } while (match)
  // Return a delimiter with one more backtick than the max number of backticks in the contents (3 ny default)
  return new Array(maxContentBackTickCount + 2).join('`')
}

function prettyTableRows(
  tableRows: readonly messages.TableRow[],
  syntax: Syntax,
  level: number
): string {
  if (tableRows.length === 0) return ''
  const maxWidths: number[] = new Array(tableRows[0].cells.length).fill(0)
  tableRows.forEach((tableRow) => {
    tableRow.cells.forEach((tableCell, j) => {
      maxWidths[j] = Math.max(maxWidths[j], escapeCell(tableCell.value).length)
    })
  })

  let n = 0
  let s = ''
  for (const row of tableRows) {
    s += prettyTableRow(row, level, maxWidths, syntax)
    if (n === 0 && syntax === 'markdown') {
      const separatorRow: messages.TableRow = {
        location: row.location,
        id: row.id + '-separator',
        cells: row.cells.map((cell, j) => ({
          location: cell.location,
          value: new Array(maxWidths[j] + 1).join('-'),
        })),
      }
      s += prettyTableRow(separatorRow, level, maxWidths, syntax)
    }
    n++
  }
  return s
}

function prettyTableRow(
  row: messages.TableRow,
  level: number,
  maxWidths: readonly number[],
  syntax: Syntax
): string {
  const actualLevel = syntax === 'markdown' ? 1 : level
  return `${spaces(actualLevel)}| ${row.cells
    .map((cell, j) => {
      const escapedCellValue = escapeCell(cell.value)
      const spaceCount = maxWidths[j] - escapedCellValue.length
      const spaces = new Array(spaceCount + 1).join(' ')
      return isNumeric(escapedCellValue) ? spaces + escapedCellValue : escapedCellValue + spaces
    })
    .join(' | ')} |\n`
}

export function escapeCell(s: string) {
  let e = ''
  const characters = s.split('')
  for (const c of characters) {
    switch (c) {
      case '\\':
        e += '\\\\'
        break
      case '\n':
        e += '\\n'
        break
      case '|':
        e += '\\|'
        break
      default:
        e += c
    }
  }
  return e
}

function isNumeric(s: string) {
  return !isNaN(parseFloat(s))
}

import * as messages from '@cucumber/messages'
import { ArrayMultimap } from '@teppeis/multimaps'

export default class Query {
  private readonly sources: messages.Source[] = []
  private readonly sourceByUri = new Map<string, messages.Source>()
  private readonly gherkinDocuments: messages.GherkinDocument[] = []
  private readonly pickles: messages.Pickle[] = []
  private readonly locationByAstNodeId = new Map<string, messages.Location>()
  private readonly gherkinStepByAstNodeId = new Map<string, messages.Step>()
  private readonly pickleIdsMapByUri = new Map<string, ArrayMultimap<string, string>>()
  private readonly pickleIdsByAstNodeId = new Map<string, string[]>()
  private readonly pickleStepIdsByAstNodeId = new Map<string, string[]>()
  // AST nodes
  private readonly featureByUriLine = new Map<string, messages.Feature>()
  private readonly backgroundByUriLine = new Map<string, messages.Background>()
  private readonly ruleByUriLine = new Map<string, messages.Rule>()
  private readonly scenarioByUriLine = new Map<string, messages.Scenario>()
  private readonly examplesByUriLine = new Map<string, messages.Examples>()
  private readonly stepByUriLine = new Map<string, messages.Step>()

  /**
   * Gets the location (line and column) of an AST node.
   * @param astNodeId
   */
  public getLocation(astNodeId: string): messages.Location {
    return this.locationByAstNodeId.get(astNodeId)
  }

  public getSources(): readonly messages.Source[] {
    return this.sources
  }

  public getGherkinDocuments(): readonly messages.GherkinDocument[] {
    return this.gherkinDocuments
  }

  public getPickles(): readonly messages.Pickle[] {
    return this.pickles
  }

  public getSource(uri: string): messages.Source | undefined {
    return this.sourceByUri.get(uri)
  }

  public getFeature(uri: string, line: number): messages.Feature | undefined {
    return getAstNode(this.featureByUriLine, uri, line)
  }

  public getBackground(uri: string, line: number): messages.Background | undefined {
    return getAstNode(this.backgroundByUriLine, uri, line)
  }

  public getRule(uri: string, line: number): messages.Rule | undefined {
    return getAstNode(this.ruleByUriLine, uri, line)
  }

  public getScenario(uri: string, line: number): messages.Scenario | undefined {
    return getAstNode(this.scenarioByUriLine, uri, line)
  }

  public getExamples(uri: string, line: number): messages.Examples | undefined {
    return getAstNode(this.examplesByUriLine, uri, line)
  }

  public getStep(uri: string, line: number): messages.Step | undefined {
    return getAstNode(this.stepByUriLine, uri, line)
  }

  /**
   * Gets all the pickle IDs
   * @param uri - the URI of the document
   * @param astNodeId - optionally restrict results to a particular AST node
   */
  public getPickleIds(uri: string, astNodeId?: string): readonly string[] {
    const pickleIdsByAstNodeId = this.pickleIdsMapByUri.get(uri)
    if (!pickleIdsByAstNodeId) {
      throw new Error(`No pickleIds for uri=${uri}`)
    }
    return astNodeId === undefined
      ? Array.from(new Set(pickleIdsByAstNodeId.values()))
      : pickleIdsByAstNodeId.get(astNodeId)
  }

  public getPickleStepIds(astNodeId: string): readonly string[] {
    return this.pickleStepIdsByAstNodeId.get(astNodeId) || []
  }

  public update(message: messages.Envelope): Query {
    if (message.source) {
      this.sources.push(message.source)
      this.sourceByUri.set(message.source.uri, message.source)
    }

    if (message.gherkinDocument) {
      this.gherkinDocuments.push(message.gherkinDocument)

      if (message.gherkinDocument.feature) {
        this.updateGherkinFeature(message.gherkinDocument.uri, message.gherkinDocument.feature)
      }
    }

    if (message.pickle) {
      const pickle = message.pickle
      this.updatePickle(pickle)
    }

    return this
  }

  private updateGherkinFeature(uri: string, feature: messages.Feature) {
    setAstNode(this.featureByUriLine, uri, feature)
    this.pickleIdsMapByUri.set(uri, new ArrayMultimap<string, string>())

    for (const featureChild of feature.children) {
      if (featureChild.background) {
        this.updateGherkinBackground(uri, featureChild.background)
      }

      if (featureChild.scenario) {
        this.updateGherkinScenario(uri, featureChild.scenario)
      }

      if (featureChild.rule) {
        this.updateGherkinRule(uri, featureChild.rule)
      }
    }
  }

  private updateGherkinBackground(uri: string, background: messages.Background) {
    setAstNode(this.backgroundByUriLine, uri, background)
    for (const step of background.steps) {
      this.updateGherkinStep(uri, step)
    }
  }

  private updateGherkinRule(uri: string, rule: messages.Rule) {
    setAstNode(this.ruleByUriLine, uri, rule)
    for (const ruleChild of rule.children) {
      if (ruleChild.background) {
        this.updateGherkinBackground(uri, ruleChild.background)
      }

      if (ruleChild.scenario) {
        this.updateGherkinScenario(uri, ruleChild.scenario)
      }
    }
  }

  private updateGherkinScenario(uri: string, scenario: messages.Scenario) {
    setAstNode(this.scenarioByUriLine, uri, scenario)
    this.locationByAstNodeId.set(scenario.id, scenario.location)
    for (const step of scenario.steps) {
      this.updateGherkinStep(uri, step)
    }

    for (const examples of scenario.examples) {
      this.updateGherkinExamples(uri, examples)
    }
  }

  private updateGherkinExamples(uri: string, examples: messages.Examples) {
    setAstNode(this.examplesByUriLine, uri, examples)
    for (const tableRow of examples.tableBody || []) {
      this.locationByAstNodeId.set(tableRow.id, tableRow.location)
    }
  }

  private updateGherkinStep(uri: string, step: messages.Step) {
    setAstNode(this.stepByUriLine, uri, step)
    this.locationByAstNodeId.set(step.id, step.location)
    this.gherkinStepByAstNodeId.set(step.id, step)
  }

  private updatePickle(pickle: messages.Pickle) {
    const pickleIdsByLineNumber = this.pickleIdsMapByUri.get(pickle.uri)

    for (const astNodeId of pickle.astNodeIds) {
      pickleIdsByLineNumber.put(astNodeId, pickle.id)
    }
    this.updatePickleSteps(pickle)
    this.pickles.push(pickle)

    for (const astNodeId of pickle.astNodeIds) {
      if (!this.pickleIdsByAstNodeId.has(astNodeId)) {
        this.pickleIdsByAstNodeId.set(astNodeId, [])
      }
      this.pickleIdsByAstNodeId.get(astNodeId).push(pickle.id)
    }
  }

  private updatePickleSteps(pickle: messages.Pickle) {
    const pickleSteps = pickle.steps
    for (const pickleStep of pickleSteps) {
      for (const astNodeId of pickleStep.astNodeIds) {
        if (!this.pickleStepIdsByAstNodeId.has(astNodeId)) {
          this.pickleStepIdsByAstNodeId.set(astNodeId, [])
        }
        this.pickleStepIdsByAstNodeId.get(astNodeId).push(pickleStep.id)
      }
    }
  }
}

type HasLocation = {
  location: messages.Location
}

function setAstNode<AstNode extends HasLocation>(
  map: Map<string, AstNode>,
  uri: string,
  astNode: AstNode
) {
  const line = astNode.location.line
  const uriLine = [uri, line].join(':')
  map.set(uriLine, astNode)
}

function getAstNode<AstNode>(
  map: Map<string, AstNode>,
  uri: string,
  line: number
): AstNode | undefined {
  const uriLine = [uri, line].join(':')
  return map.get(uriLine)
}

