import DataTable from './data_table'
import Definition, {
  IDefinition,
  IGetInvocationDataRequest,
  IGetInvocationDataResponse,
  IStepDefinitionParameters,
} from './definition'
import { parseStepArgument } from '../step_arguments'
import { Expression } from '@cucumber/cucumber-expressions'
import { doesHaveValue } from '../value_checker'
import { GherkinStepKeyword } from './gherkin_step_keyword'

export default class StepDefinition extends Definition implements IDefinition {
  public readonly keyword: GherkinStepKeyword
  public readonly pattern: string | RegExp
  public readonly expression: Expression

  constructor(data: IStepDefinitionParameters) {
    super(data)
    this.keyword = data.keyword
    this.pattern = data.pattern
    this.expression = data.expression
  }

  async getInvocationParameters({
    step,
    world,
  }: IGetInvocationDataRequest): Promise<IGetInvocationDataResponse> {
    const parameters = await Promise.all(
      this.expression.match(step.text).map((arg) => arg.getValue(world))
    )
    if (doesHaveValue(step.argument)) {
      const argumentParamater = parseStepArgument<any>(step.argument, {
        dataTable: (arg) => new DataTable(arg),
        docString: (arg) => arg.content,
      })
      parameters.push(argumentParamater)
    }
    return {
      getInvalidCodeLengthMessage: () =>
        this.baseGetInvalidCodeLengthMessage(parameters),
      parameters,
      validCodeLengths: [parameters.length, parameters.length + 1],
    }
  }

  matchesStepName(stepName: string): boolean {
    return doesHaveValue(this.expression.match(stepName))
  }
}

import * as messages from '@cucumber/messages'

export default class DataTable {
  private readonly rawTable: string[][]

  constructor(sourceTable: messages.PickleTable | string[][]) {
    if (sourceTable instanceof Array) {
      this.rawTable = sourceTable
    } else {
      this.rawTable = sourceTable.rows.map((row) =>
        row.cells.map((cell) => cell.value)
      )
    }
  }

  hashes(): Record<string, string>[] {
    const copy = this.raw()
    const keys = copy[0]
    const valuesArray = copy.slice(1)
    return valuesArray.map((values) => {
      const rowObject: Record<string, string> = {}
      keys.forEach((key, index) => (rowObject[key] = values[index]))
      return rowObject
    })
  }

  raw(): string[][] {
    return this.rawTable.slice(0)
  }

  rows(): string[][] {
    const copy = this.raw()
    copy.shift()
    return copy
  }

  rowsHash(): Record<string, string> {
    const rows = this.raw()
    const everyRowHasTwoColumns = rows.every((row) => row.length === 2)
    if (!everyRowHasTwoColumns) {
      throw new Error(
        'rowsHash can only be called on a data table where all rows have exactly two columns'
      )
    }
    const result: Record<string, string> = {}
    rows.forEach((x) => (result[x[0]] = x[1]))
    return result
  }

  transpose(): DataTable {
    const transposed = this.rawTable[0].map((x, i) =>
      this.rawTable.map((y) => y[i])
    )
    return new DataTable(transposed)
  }
}

import { DefineStepPattern, IDefineStepOptions } from './types'

interface IValidation {
  identifier: string
  expectedType: string
  predicate: (args: any) => boolean
}

interface IDefineStepArguments {
  pattern?: DefineStepPattern
  options?: IDefineStepOptions
  code?: Function
}

const optionsValidation = {
  expectedType: 'object or function',
  predicate({ options }: IDefineStepArguments) {
    return typeof options === 'object'
  },
}

const optionsTimeoutValidation = {
  identifier: '"options.timeout"',
  expectedType: 'integer',
  predicate({ options }: IDefineStepArguments) {
    return options.timeout == null || typeof options.timeout === 'number'
  },
}

const fnValidation = {
  expectedType: 'function',
  predicate({ code }: IDefineStepArguments) {
    return typeof code === 'function'
  },
}

const validations: Record<string, IValidation[]> = {
  defineTestRunHook: [
    { identifier: 'first argument', ...optionsValidation },
    optionsTimeoutValidation,
    { identifier: 'second argument', ...fnValidation },
  ],
  defineTestCaseHook: [
    { identifier: 'first argument', ...optionsValidation },
    {
      identifier: '"options.tags"',
      expectedType: 'string',
      predicate({ options }) {
        return options.tags == null || typeof options.tags === 'string'
      },
    },
    optionsTimeoutValidation,
    { identifier: 'second argument', ...fnValidation },
  ],
  defineTestStepHook: [
    { identifier: 'first argument', ...optionsValidation },
    {
      identifier: '"options.tags"',
      expectedType: 'string',
      predicate({ options }) {
        return options.tags == null || typeof options.tags === 'string'
      },
    },
    optionsTimeoutValidation,
    { identifier: 'second argument', ...fnValidation },
  ],
  defineStep: [
    {
      identifier: 'first argument',
      expectedType: 'string or regular expression',
      predicate({ pattern }) {
        return pattern instanceof RegExp || typeof pattern === 'string'
      },
    },
    { identifier: 'second argument', ...optionsValidation },
    optionsTimeoutValidation,
    { identifier: 'third argument', ...fnValidation },
  ],
}

export default function validateArguments({
  args,
  fnName,
  location,
}: {
  args?: IDefineStepArguments
  fnName: string
  location: string
}): void {
  validations[fnName].forEach(({ identifier, expectedType, predicate }) => {
    if (!predicate(args)) {
      throw new Error(
        `${location}: Invalid ${identifier}: should be a ${expectedType}`
      )
    }
  })
}

