export class SourcedParameterTypeRegistry extends ParameterTypeRegistry {
  private parameterTypeToSource: WeakMap<ParameterType<unknown>, ILineAndUri> =
    new WeakMap()

  defineSourcedParameterType(
    parameterType: ParameterType<unknown>,
    source: ILineAndUri
  ) {
    this.defineParameterType(parameterType)
    this.parameterTypeToSource.set(parameterType, source)
  }

  lookupSource(parameterType: ParameterType<unknown>) {
    return this.parameterTypeToSource.get(parameterType)
  }
}

/**
 * Provides a try guarded require call that will throw a more detailed error when
 * the ERR_REQUIRE_ESM error code is encountered.
 *
 * @param {string} path File path to require from.
 */
export default function tryRequire(path: string) {
  try {
    return require(path)
  } catch (error) {
    if (error.code === 'ERR_REQUIRE_ESM') {
      throw Error(
        `Cucumber expected a CommonJS module at '${path}' but found an ES module.
      Either change the file to CommonJS syntax or use the --import directive instead of --require.

      Original error message: ${error.message}`
      )
    } else {
      throw error
    }
  }
}

import { Envelope, IdGenerator, ParseError } from '@cucumber/messages'
import { EventEmitter } from 'events'
import { EventDataCollector } from '../formatter/helpers'
import { emitMetaMessage, emitSupportCodeMessages } from '../cli/helpers'
import { IRunOptions, IRunEnvironment, IRunResult } from './types'
import { resolvePaths } from './paths'
import { makeRuntime } from './runtime'
import { initializeFormatters } from './formatters'
import { getSupportCodeLibrary } from './support'
import { mergeEnvironment } from './environment'
import { getFilteredPicklesAndErrors } from './gherkin'
import { initializePlugins } from './plugins'
import { ConsoleLogger } from './console_logger'
import { ILogger } from '../logger'

/**
 * Execute a Cucumber test run.
 *
 * @public
 * @param configuration - Configuration loaded from `loadConfiguration`.
 * @param environment - Project environment.
 * @param onMessage - Callback fired each time Cucumber emits a message.
 */
export async function runCucumber(
  configuration: IRunOptions,
  environment: IRunEnvironment = {},
  onMessage?: (message: Envelope) => void
): Promise<IRunResult> {
  const { cwd, stdout, stderr, env, debug } = mergeEnvironment(environment)
  const logger: ILogger = new ConsoleLogger(stderr, debug)

  const newId = IdGenerator.uuid()

  const supportCoordinates =
    'World' in configuration.support
      ? configuration.support.originalCoordinates
      : configuration.support

  const { unexpandedFeaturePaths, featurePaths, requirePaths, importPaths } =
    await resolvePaths(logger, cwd, configuration.sources, supportCoordinates)

  const supportCodeLibrary =
    'World' in configuration.support
      ? configuration.support
      : await getSupportCodeLibrary({
          cwd,
          newId,
          requirePaths,
          importPaths,
          requireModules: supportCoordinates.requireModules,
        })

  const plugins = await initializePlugins(logger, configuration, environment)

  const eventBroadcaster = new EventEmitter()
  if (onMessage) {
    eventBroadcaster.on('envelope', onMessage)
  }
  eventBroadcaster.on('envelope', (value) => plugins.emit('message', value))
  const eventDataCollector = new EventDataCollector(eventBroadcaster)

  let formatterStreamError = false
  const cleanupFormatters = await initializeFormatters({
    env,
    cwd,
    stdout,
    stderr,
    logger,
    onStreamError: () => (formatterStreamError = true),
    eventBroadcaster,
    eventDataCollector,
    configuration: configuration.formats,
    supportCodeLibrary,
  })
  await emitMetaMessage(eventBroadcaster, env)

  let pickleIds: string[] = []
  let parseErrors: ParseError[] = []
  if (featurePaths.length > 0) {
    const gherkinResult = await getFilteredPicklesAndErrors({
      newId,
      cwd,
      logger,
      unexpandedFeaturePaths,
      featurePaths,
      coordinates: configuration.sources,
      onEnvelope: (envelope) => eventBroadcaster.emit('envelope', envelope),
    })
    pickleIds = gherkinResult.filteredPickles.map(({ pickle }) => pickle.id)
    parseErrors = gherkinResult.parseErrors
  }
  if (parseErrors.length) {
    parseErrors.forEach((parseError) => {
      logger.error(
        `Parse error in "${parseError.source.uri}" ${parseError.message}`
      )
    })
    await cleanupFormatters()
    await plugins.cleanup()
    return {
      success: false,
      support: supportCodeLibrary,
    }
  }

  emitSupportCodeMessages({
    eventBroadcaster,
    supportCodeLibrary,
    newId,
  })

  const runtime = makeRuntime({
    cwd,
    logger,
    eventBroadcaster,
    eventDataCollector,
    pickleIds,
    newId,
    supportCodeLibrary,
    requireModules: supportCoordinates.requireModules,
    requirePaths,
    importPaths,
    options: configuration.runtime,
  })
  const success = await runtime.start()
  await cleanupFormatters()
  await plugins.cleanup()

  return {
    success: success && !formatterStreamError,
    support: supportCodeLibrary,
  }
}

import * as messages from '@cucumber/messages'
import { IdGenerator } from '@cucumber/messages'
import { EventEmitter } from 'events'
import { EventDataCollector } from '../formatter/helpers'
import { ISupportCodeLibrary } from '../support_code_library_builder/types'
import { assembleTestCases } from './assemble_test_cases'
import { retriesForPickle, shouldCauseFailure } from './helpers'
import { makeRunTestRunHooks, RunsTestRunHooks } from './run_test_run_hooks'
import { IStopwatch, create } from './stopwatch'
import TestCaseRunner from './test_case_runner'

export interface IRuntime {
  start: () => Promise<boolean>
}

export interface INewRuntimeOptions {
  eventBroadcaster: EventEmitter
  eventDataCollector: EventDataCollector
  newId: IdGenerator.NewId
  options: IRuntimeOptions
  pickleIds: string[]
  supportCodeLibrary: ISupportCodeLibrary
}

export interface IRuntimeOptions {
  dryRun: boolean
  failFast: boolean
  filterStacktraces: boolean
  retry: number
  retryTagFilter: string
  strict: boolean
  worldParameters: any
}

export default class Runtime implements IRuntime {
  private readonly eventBroadcaster: EventEmitter
  private readonly eventDataCollector: EventDataCollector
  private readonly stopwatch: IStopwatch
  private readonly newId: IdGenerator.NewId
  private readonly options: IRuntimeOptions
  private readonly pickleIds: string[]
  private readonly supportCodeLibrary: ISupportCodeLibrary
  private success: boolean
  private runTestRunHooks: RunsTestRunHooks

  constructor({
    eventBroadcaster,
    eventDataCollector,
    newId,
    options,
    pickleIds,
    supportCodeLibrary,
  }: INewRuntimeOptions) {
    this.eventBroadcaster = eventBroadcaster
    this.eventDataCollector = eventDataCollector
    this.stopwatch = create()
    this.newId = newId
    this.options = options
    this.pickleIds = pickleIds
    this.supportCodeLibrary = supportCodeLibrary
    this.success = true
    this.runTestRunHooks = makeRunTestRunHooks(
      this.options.dryRun,
      this.supportCodeLibrary.defaultTimeout,
      (name, location) => `${name} hook errored, process exiting: ${location}`
    )
  }

  async runTestCase(
    pickleId: string,
    testCase: messages.TestCase
  ): Promise<void> {
    const pickle = this.eventDataCollector.getPickle(pickleId)
    const retries = retriesForPickle(pickle, this.options)
    const skip = this.options.dryRun || (this.options.failFast && !this.success)
    const testCaseRunner = new TestCaseRunner({
      eventBroadcaster: this.eventBroadcaster,
      stopwatch: this.stopwatch,
      gherkinDocument: this.eventDataCollector.getGherkinDocument(pickle.uri),
      newId: this.newId,
      pickle,
      testCase,
      retries,
      skip,
      filterStackTraces: this.options.filterStacktraces,
      supportCodeLibrary: this.supportCodeLibrary,
      worldParameters: this.options.worldParameters,
    })
    const status = await testCaseRunner.run()
    if (shouldCauseFailure(status, this.options)) {
      this.success = false
    }
  }

  async start(): Promise<boolean> {
    const testRunStarted: messages.Envelope = {
      testRunStarted: {
        timestamp: this.stopwatch.timestamp(),
      },
    }
    this.eventBroadcaster.emit('envelope', testRunStarted)
    this.stopwatch.start()
    await this.runTestRunHooks(
      this.supportCodeLibrary.beforeTestRunHookDefinitions,
      'a BeforeAll'
    )
    const assembledTestCases = await assembleTestCases({
      eventBroadcaster: this.eventBroadcaster,
      newId: this.newId,
      pickles: this.pickleIds.map((pickleId) =>
        this.eventDataCollector.getPickle(pickleId)
      ),
      supportCodeLibrary: this.supportCodeLibrary,
    })
    for (const pickleId of this.pickleIds) {
      await this.runTestCase(pickleId, assembledTestCases[pickleId])
    }
    await this.runTestRunHooks(
      this.supportCodeLibrary.afterTestRunHookDefinitions.slice(0).reverse(),
      'an AfterAll'
    )
    this.stopwatch.stop()
    const testRunFinished: messages.Envelope = {
      testRunFinished: {
        timestamp: this.stopwatch.timestamp(),
        success: this.success,
      },
    }
    this.eventBroadcaster.emit('envelope', testRunFinished)
    return this.success
  }
}

import { EventEmitter } from 'events'
import * as messages from '@cucumber/messages'
import { IdGenerator } from '@cucumber/messages'
import { ISupportCodeLibrary } from '../support_code_library_builder/types'
import { Group } from '@cucumber/cucumber-expressions'
import { doesHaveValue } from '../value_checker'

export declare type IAssembledTestCases = Record<string, messages.TestCase>

export interface IAssembleTestCasesOptions {
  eventBroadcaster: EventEmitter
  newId: IdGenerator.NewId
  pickles: messages.Pickle[]
  supportCodeLibrary: ISupportCodeLibrary
}

export async function assembleTestCases({
  eventBroadcaster,
  newId,
  pickles,
  supportCodeLibrary,
}: IAssembleTestCasesOptions): Promise<IAssembledTestCases> {
  const result: IAssembledTestCases = {}
  for (const pickle of pickles) {
    const { id: pickleId } = pickle
    const testCaseId = newId()
    const fromBeforeHooks: messages.TestStep[] = makeBeforeHookSteps({
      supportCodeLibrary,
      pickle,
      newId,
    })
    const fromStepDefinitions: messages.TestStep[] = makeSteps({
      pickle,
      supportCodeLibrary,
      newId,
    })
    const fromAfterHooks: messages.TestStep[] = makeAfterHookSteps({
      supportCodeLibrary,
      pickle,
      newId,
    })
    const testCase: messages.TestCase = {
      pickleId,
      id: testCaseId,
      testSteps: [
        ...fromBeforeHooks,
        ...fromStepDefinitions,
        ...fromAfterHooks,
      ],
    }
    eventBroadcaster.emit('envelope', { testCase })
    result[pickleId] = testCase
  }
  return result
}

function makeAfterHookSteps({
  supportCodeLibrary,
  pickle,
  newId,
}: {
  supportCodeLibrary: ISupportCodeLibrary
  pickle: messages.Pickle
  newId: IdGenerator.NewId
}): messages.TestStep[] {
  return supportCodeLibrary.afterTestCaseHookDefinitions
    .slice(0)
    .reverse()
    .filter((hookDefinition) => hookDefinition.appliesToTestCase(pickle))
    .map((hookDefinition) => ({
      id: newId(),
      hookId: hookDefinition.id,
    }))
}

function makeBeforeHookSteps({
  supportCodeLibrary,
  pickle,
  newId,
}: {
  supportCodeLibrary: ISupportCodeLibrary
  pickle: messages.Pickle
  newId: IdGenerator.NewId
}): messages.TestStep[] {
  return supportCodeLibrary.beforeTestCaseHookDefinitions
    .filter((hookDefinition) => hookDefinition.appliesToTestCase(pickle))
    .map((hookDefinition) => ({
      id: newId(),
      hookId: hookDefinition.id,
    }))
}

function makeSteps({
  pickle,
  supportCodeLibrary,
  newId,
}: {
  pickle: messages.Pickle
  supportCodeLibrary: ISupportCodeLibrary
  newId: () => string
}): messages.TestStep[] {
  return pickle.steps.map((pickleStep) => {
    const stepDefinitions = supportCodeLibrary.stepDefinitions.filter(
      (stepDefinition) => stepDefinition.matchesStepName(pickleStep.text)
    )
    return {
      id: newId(),
      pickleStepId: pickleStep.id,
      stepDefinitionIds: stepDefinitions.map(
        (stepDefinition) => stepDefinition.id
      ),
      stepMatchArgumentsLists: stepDefinitions.map((stepDefinition) => {
        const result = stepDefinition.expression.match(pickleStep.text)
        return {
          stepMatchArguments: result.map((arg) => {
            return {
              group: mapArgumentGroup(arg.group),
              parameterTypeName: arg.parameterType.name,
            }
          }),
        }
      }),
    }
  })
}

function mapArgumentGroup(group: Group): messages.Group {
  return {
    start: group.start,
    value: group.value,
    children: doesHaveValue(group.children)
      ? group.children.map((child) => mapArgumentGroup(child))
      : undefined,
  }
}

import { formatLocation } from '../formatter/helpers/location_helpers'
import Table from 'cli-table3'
import indentString from 'indent-string'
import { PickleTagFilter } from '../pickle_filter'
import StepDefinition from '../models/step_definition'
import * as messages from '@cucumber/messages'
import { IRuntimeOptions } from '.'

export function getAmbiguousStepException(
  stepDefinitions: StepDefinition[]
): string {
  const table = new Table({
    chars: {
      bottom: '',
      'bottom-left': '',
      'bottom-mid': '',
      'bottom-right': '',
      left: '',
      'left-mid': '',
      mid: '',
      'mid-mid': '',
      middle: ' - ',
      right: '',
      'right-mid': '',
      top: '',
      'top-left': '',
      'top-mid': '',
      'top-right': '',
    },
    style: {
      border: [],
      'padding-left': 0,
      'padding-right': 0,
    },
  })
  table.push(
    ...stepDefinitions.map((stepDefinition) => {
      const pattern = stepDefinition.pattern.toString()
      return [pattern, formatLocation(stepDefinition)]
    })
  )
  return `${'Multiple step definitions match:' + '\n'}${indentString(
    table.toString(),
    2
  )}`
}

export function retriesForPickle(
  pickle: messages.Pickle,
  options: IRuntimeOptions
): number {
  if (!options.retry) {
    return 0
  }
  const retries = options.retry
  if (retries === 0) {
    return 0
  }
  const retryTagFilter = options.retryTagFilter
  if (!retryTagFilter) {
    return retries
  }
  const pickleTagFilter = new PickleTagFilter(retryTagFilter)
  if (pickleTagFilter.matchesAllTagExpressions(pickle)) {
    return retries
  }
  return 0
}

export function shouldCauseFailure(
  status: messages.TestStepResultStatus,
  options: IRuntimeOptions
): boolean {
  if (options.dryRun) {
    return false
  }
  const failureStatuses: messages.TestStepResultStatus[] = [
    messages.TestStepResultStatus.AMBIGUOUS,
    messages.TestStepResultStatus.FAILED,
    messages.TestStepResultStatus.UNDEFINED,
  ]
  if (options.strict) {
    failureStatuses.push(messages.TestStepResultStatus.PENDING)
  }
  return failureStatuses.includes(status)
}

