import { wrapPromiseWithTimeout } from './time'
import UncaughtExceptionManager from './uncaught_exception_manager'
import util from 'util'
import { doesHaveValue } from './value_checker'

export interface IRunRequest {
  argsArray: any[]
  thisArg: any
  fn: Function
  timeoutInMilliseconds: number
}

export interface IRunResponse {
  error?: any
  result?: any
}

const UserCodeRunner = {
  async run({
    argsArray,
    thisArg,
    fn,
    timeoutInMilliseconds,
  }: IRunRequest): Promise<IRunResponse> {
    const callbackPromise = new Promise((resolve, reject) => {
      argsArray.push((error: Error, result: IRunResponse) => {
        if (doesHaveValue(error)) {
          reject(error)
        } else {
          resolve(result)
        }
      })
    })

    let fnReturn
    try {
      fnReturn = fn.apply(thisArg, argsArray)
    } catch (e) {
      const error = e instanceof Error ? e : util.format(e)
      return { error }
    }

    const racingPromises = []
    const callbackInterface = fn.length === argsArray.length
    const promiseInterface =
      doesHaveValue(fnReturn) && typeof fnReturn.then === 'function'

    if (callbackInterface && promiseInterface) {
      return {
        error: new Error(
          'function uses multiple asynchronous interfaces: callback and promise\n' +
            'to use the callback interface: do not return a promise\n' +
            'to use the promise interface: remove the last argument to the function'
        ),
      }
    } else if (callbackInterface) {
      racingPromises.push(callbackPromise)
    } else if (promiseInterface) {
      racingPromises.push(fnReturn)
    } else {
      return { result: fnReturn }
    }

    let exceptionHandler
    const uncaughtExceptionPromise = new Promise((resolve, reject) => {
      exceptionHandler = reject
      UncaughtExceptionManager.registerHandler(exceptionHandler)
    })
    racingPromises.push(uncaughtExceptionPromise)

    let finalPromise = Promise.race(racingPromises)
    if (timeoutInMilliseconds >= 0) {
      const timeoutMessage =
        'function timed out, ensure the ' +
        (callbackInterface ? 'callback is executed' : 'promise resolves') +
        ` within ${timeoutInMilliseconds.toString()} milliseconds`
      finalPromise = wrapPromiseWithTimeout(
        finalPromise,
        timeoutInMilliseconds,
        timeoutMessage
      )
    }

    let error, result
    try {
      result = await finalPromise
    } catch (e) {
      if (e instanceof Error) {
        error = e
      } else if (doesHaveValue(e)) {
        error = util.format(e)
      } else {
        error = new Error('Promise rejected without a reason')
      }
    }

    UncaughtExceptionManager.unregisterHandler(exceptionHandler)

    return { error, result }
  },
}

export default UserCodeRunner

import UncaughtExceptionListener = NodeJS.UncaughtExceptionListener

const UncaughtExceptionManager = {
  registerHandler(handler: UncaughtExceptionListener): void {
    process.addListener('uncaughtException', handler)
  },

  unregisterHandler(handler: UncaughtExceptionListener): void {
    process.removeListener('uncaughtException', handler)
  },
}

export default UncaughtExceptionManager

import { Duration, TimeConversion, Timestamp } from '@cucumber/messages'
import methods from '../time'

/**
 * A utility for timing test run operations and returning duration and
 * timestamp objects in messages-compatible formats
 */
export interface IStopwatch {
  start: () => IStopwatch
  stop: () => IStopwatch
  duration: () => Duration
  timestamp: () => Timestamp
}

class StopwatchImpl implements IStopwatch {
  private started: number

  constructor(private base: Duration = { seconds: 0, nanos: 0 }) {}

  start(): IStopwatch {
    this.started = methods.performance.now()
    return this
  }

  stop(): IStopwatch {
    this.base = this.duration()
    this.started = undefined
    return this
  }

  duration(): Duration {
    if (typeof this.started !== 'number') {
      return this.base
    }
    return TimeConversion.addDurations(
      this.base,
      TimeConversion.millisecondsToDuration(
        methods.performance.now() - this.started
      )
    )
  }

  timestamp(): Timestamp {
    return TimeConversion.millisecondsSinceEpochToTimestamp(methods.Date.now())
  }
}

export const create = (base?: Duration): IStopwatch => new StopwatchImpl(base)

import { getAmbiguousStepException } from './helpers'
import AttachmentManager from './attachment_manager'
import StepRunner from './step_runner'
import * as messages from '@cucumber/messages'
import { getWorstTestStepResult, IdGenerator } from '@cucumber/messages'
import { EventEmitter } from 'events'
import {
  ISupportCodeLibrary,
  ITestCaseHookParameter,
  ITestStepHookParameter,
} from '../support_code_library_builder/types'
import TestCaseHookDefinition from '../models/test_case_hook_definition'
import TestStepHookDefinition from '../models/test_step_hook_definition'
import { IDefinition } from '../models/definition'
import { doesHaveValue, doesNotHaveValue } from '../value_checker'
import { IStopwatch } from './stopwatch'
import StepDefinition from '../models/step_definition'

export interface INewTestCaseRunnerOptions {
  eventBroadcaster: EventEmitter
  stopwatch: IStopwatch
  gherkinDocument: messages.GherkinDocument
  newId: IdGenerator.NewId
  pickle: messages.Pickle
  testCase: messages.TestCase
  retries: number
  skip: boolean
  filterStackTraces: boolean
  supportCodeLibrary: ISupportCodeLibrary
  worldParameters: any
}

export default class TestCaseRunner {
  private readonly attachmentManager: AttachmentManager
  private currentTestCaseStartedId: string
  private currentTestStepId: string
  private readonly eventBroadcaster: EventEmitter
  private readonly stopwatch: IStopwatch
  private readonly gherkinDocument: messages.GherkinDocument
  private readonly newId: IdGenerator.NewId
  private readonly pickle: messages.Pickle
  private readonly testCase: messages.TestCase
  private readonly maxAttempts: number
  private readonly skip: boolean
  private readonly filterStackTraces: boolean
  private readonly supportCodeLibrary: ISupportCodeLibrary
  private testStepResults: messages.TestStepResult[]
  private world: any
  private readonly worldParameters: any

  constructor({
    eventBroadcaster,
    stopwatch,
    gherkinDocument,
    newId,
    pickle,
    testCase,
    retries = 0,
    skip,
    filterStackTraces,
    supportCodeLibrary,
    worldParameters,
  }: INewTestCaseRunnerOptions) {
    this.attachmentManager = new AttachmentManager(
      ({ data, media, fileName }) => {
        if (doesNotHaveValue(this.currentTestStepId)) {
          throw new Error(
            'Cannot attach when a step/hook is not running. Ensure your step/hook waits for the attach to finish.'
          )
        }
        const attachment: messages.Envelope = {
          attachment: {
            body: data,
            contentEncoding: media.encoding,
            mediaType: media.contentType,
            fileName,
            testCaseStartedId: this.currentTestCaseStartedId,
            testStepId: this.currentTestStepId,
          },
        }
        this.eventBroadcaster.emit('envelope', attachment)
      }
    )
    this.eventBroadcaster = eventBroadcaster
    this.stopwatch = stopwatch
    this.gherkinDocument = gherkinDocument
    this.maxAttempts = 1 + (skip ? 0 : retries)
    this.newId = newId
    this.pickle = pickle
    this.testCase = testCase
    this.skip = skip
    this.filterStackTraces = filterStackTraces
    this.supportCodeLibrary = supportCodeLibrary
    this.worldParameters = worldParameters
    this.resetTestProgressData()
  }

  resetTestProgressData(): void {
    this.world = new this.supportCodeLibrary.World({
      attach: this.attachmentManager.create.bind(this.attachmentManager),
      log: this.attachmentManager.log.bind(this.attachmentManager),
      parameters: this.worldParameters,
    })
    this.testStepResults = []
  }

  getBeforeStepHookDefinitions(): TestStepHookDefinition[] {
    return this.supportCodeLibrary.beforeTestStepHookDefinitions.filter(
      (hookDefinition) => hookDefinition.appliesToTestCase(this.pickle)
    )
  }

  getAfterStepHookDefinitions(): TestStepHookDefinition[] {
    return this.supportCodeLibrary.afterTestStepHookDefinitions
      .slice(0)
      .reverse()
      .filter((hookDefinition) => hookDefinition.appliesToTestCase(this.pickle))
  }

  getWorstStepResult(): messages.TestStepResult {
    if (this.testStepResults.length === 0) {
      return {
        status: this.skip
          ? messages.TestStepResultStatus.SKIPPED
          : messages.TestStepResultStatus.PASSED,
        duration: messages.TimeConversion.millisecondsToDuration(0),
      }
    }
    return getWorstTestStepResult(this.testStepResults)
  }

  async invokeStep(
    step: messages.PickleStep,
    stepDefinition: IDefinition,
    hookParameter?: any
  ): Promise<messages.TestStepResult> {
    return await StepRunner.run({
      defaultTimeout: this.supportCodeLibrary.defaultTimeout,
      filterStackTraces: this.filterStackTraces,
      hookParameter,
      step,
      stepDefinition,
      world: this.world,
    })
  }

  isSkippingSteps(): boolean {
    return (
      this.getWorstStepResult().status !== messages.TestStepResultStatus.PASSED
    )
  }

  shouldSkipHook(isBeforeHook: boolean): boolean {
    return this.skip || (this.isSkippingSteps() && isBeforeHook)
  }

  async aroundTestStep(
    testStepId: string,
    runStepFn: () => Promise<messages.TestStepResult>
  ): Promise<void> {
    const testStepStarted: messages.Envelope = {
      testStepStarted: {
        testCaseStartedId: this.currentTestCaseStartedId,
        testStepId,
        timestamp: this.stopwatch.timestamp(),
      },
    }
    this.eventBroadcaster.emit('envelope', testStepStarted)
    this.currentTestStepId = testStepId
    const testStepResult = await runStepFn()
    this.currentTestStepId = null
    this.testStepResults.push(testStepResult)
    const testStepFinished: messages.Envelope = {
      testStepFinished: {
        testCaseStartedId: this.currentTestCaseStartedId,
        testStepId,
        testStepResult,
        timestamp: this.stopwatch.timestamp(),
      },
    }
    this.eventBroadcaster.emit('envelope', testStepFinished)
  }

  async run(): Promise<messages.TestStepResultStatus> {
    for (let attempt = 0; attempt < this.maxAttempts; attempt++) {
      const moreAttemptsRemaining = attempt + 1 < this.maxAttempts

      const willBeRetried = await this.runAttempt(
        attempt,
        moreAttemptsRemaining
      )

      if (!willBeRetried) {
        break
      }
      this.resetTestProgressData()
    }
    return this.getWorstStepResult().status
  }

  async runAttempt(
    attempt: number,
    moreAttemptsRemaining: boolean
  ): Promise<boolean> {
    this.currentTestCaseStartedId = this.newId()
    const testCaseStarted: messages.Envelope = {
      testCaseStarted: {
        attempt,
        testCaseId: this.testCase.id,
        id: this.currentTestCaseStartedId,
        timestamp: this.stopwatch.timestamp(),
      },
    }
    this.eventBroadcaster.emit('envelope', testCaseStarted)
    // used to determine whether a hook is a Before or After
    let didWeRunStepsYet = false
    for (const testStep of this.testCase.testSteps) {
      await this.aroundTestStep(testStep.id, async () => {
        if (doesHaveValue(testStep.hookId)) {
          const hookParameter: ITestCaseHookParameter = {
            gherkinDocument: this.gherkinDocument,
            pickle: this.pickle,
            testCaseStartedId: this.currentTestCaseStartedId,
          }
          if (didWeRunStepsYet) {
            hookParameter.result = this.getWorstStepResult()
            hookParameter.willBeRetried =
              this.getWorstStepResult().status ===
                messages.TestStepResultStatus.FAILED && moreAttemptsRemaining
          }
          return await this.runHook(
            findHookDefinition(testStep.hookId, this.supportCodeLibrary),
            hookParameter,
            !didWeRunStepsYet
          )
        } else {
          const pickleStep = this.pickle.steps.find(
            (pickleStep) => pickleStep.id === testStep.pickleStepId
          )
          const testStepResult = await this.runStep(pickleStep, testStep)
          didWeRunStepsYet = true
          return testStepResult
        }
      })
    }

    const willBeRetried =
      this.getWorstStepResult().status ===
        messages.TestStepResultStatus.FAILED && moreAttemptsRemaining
    const testCaseFinished: messages.Envelope = {
      testCaseFinished: {
        testCaseStartedId: this.currentTestCaseStartedId,
        timestamp: this.stopwatch.timestamp(),
        willBeRetried,
      },
    }
    this.eventBroadcaster.emit('envelope', testCaseFinished)

    return willBeRetried
  }

  async runHook(
    hookDefinition: TestCaseHookDefinition,
    hookParameter: ITestCaseHookParameter,
    isBeforeHook: boolean
  ): Promise<messages.TestStepResult> {
    if (this.shouldSkipHook(isBeforeHook)) {
      return {
        status: messages.TestStepResultStatus.SKIPPED,
        duration: messages.TimeConversion.millisecondsToDuration(0),
      }
    }
    return await this.invokeStep(null, hookDefinition, hookParameter)
  }

  async runStepHooks(
    stepHooks: TestStepHookDefinition[],
    pickleStep: messages.PickleStep,
    stepResult?: messages.TestStepResult
  ): Promise<messages.TestStepResult[]> {
    const stepHooksResult = []
    const hookParameter: ITestStepHookParameter = {
      gherkinDocument: this.gherkinDocument,
      pickle: this.pickle,
      pickleStep,
      testCaseStartedId: this.currentTestCaseStartedId,
      testStepId: this.currentTestStepId,
      result: stepResult,
    }
    for (const stepHookDefinition of stepHooks) {
      stepHooksResult.push(
        await this.invokeStep(null, stepHookDefinition, hookParameter)
      )
    }
    return stepHooksResult
  }

  async runStep(
    pickleStep: messages.PickleStep,
    testStep: messages.TestStep
  ): Promise<messages.TestStepResult> {
    const stepDefinitions = testStep.stepDefinitionIds.map(
      (stepDefinitionId) => {
        return findStepDefinition(stepDefinitionId, this.supportCodeLibrary)
      }
    )
    if (stepDefinitions.length === 0) {
      return {
        status: messages.TestStepResultStatus.UNDEFINED,
        duration: messages.TimeConversion.millisecondsToDuration(0),
      }
    } else if (stepDefinitions.length > 1) {
      return {
        message: getAmbiguousStepException(stepDefinitions),
        status: messages.TestStepResultStatus.AMBIGUOUS,
        duration: messages.TimeConversion.millisecondsToDuration(0),
      }
    } else if (this.isSkippingSteps()) {
      return {
        status: messages.TestStepResultStatus.SKIPPED,
        duration: messages.TimeConversion.millisecondsToDuration(0),
      }
    }

    let stepResult
    let stepResults = await this.runStepHooks(
      this.getBeforeStepHookDefinitions(),
      pickleStep
    )
    if (
      getWorstTestStepResult(stepResults).status !==
      messages.TestStepResultStatus.FAILED
    ) {
      stepResult = await this.invokeStep(pickleStep, stepDefinitions[0])
      stepResults.push(stepResult)
    }
    const afterStepHookResults = await this.runStepHooks(
      this.getAfterStepHookDefinitions(),
      pickleStep,
      stepResult
    )
    stepResults = stepResults.concat(afterStepHookResults)

    const finalStepResult = getWorstTestStepResult(stepResults)
    let finalDuration = messages.TimeConversion.millisecondsToDuration(0)
    for (const result of stepResults) {
      finalDuration = messages.TimeConversion.addDurations(
        finalDuration,
        result.duration
      )
    }
    finalStepResult.duration = finalDuration
    return finalStepResult
  }
}

function findHookDefinition(
  id: string,
  supportCodeLibrary: ISupportCodeLibrary
): TestCaseHookDefinition {
  return [
    ...supportCodeLibrary.beforeTestCaseHookDefinitions,
    ...supportCodeLibrary.afterTestCaseHookDefinitions,
  ].find((definition) => definition.id === id)
}

function findStepDefinition(
  id: string,
  supportCodeLibrary: ISupportCodeLibrary
): StepDefinition {
  return supportCodeLibrary.stepDefinitions.find(
    (definition) => definition.id === id
  )
}

import isStream from 'is-stream'
import { Readable } from 'stream'
import * as messages from '@cucumber/messages'
import { doesHaveValue, doesNotHaveValue } from '../../value_checker'

export interface IAttachmentMedia {
  encoding: messages.AttachmentContentEncoding
  contentType: string
}

export interface IAttachment {
  data: string
  media: IAttachmentMedia
  fileName?: string
}

export type IAttachFunction = (attachment: IAttachment) => void

export interface ICreateAttachmentOptions {
  mediaType: string
  fileName?: string
}
export type ICreateStringAttachment = (
  data: string,
  mediaTypeOrOptions?: string | ICreateAttachmentOptions
) => void
export type ICreateBufferAttachment = (
  data: Buffer,
  mediaTypeOrOptions: string | ICreateAttachmentOptions
) => void
export type ICreateStreamAttachment = (
  data: Readable,
  mediaTypeOrOptions: string | ICreateAttachmentOptions
) => Promise<void>
export type ICreateStreamAttachmentWithCallback = (
  data: Readable,
  mediaTypeOrOptions: string | ICreateAttachmentOptions,
  callback: () => void
) => void
export type ICreateAttachment = ICreateStringAttachment &
  ICreateBufferAttachment &
  ICreateStreamAttachment &
  ICreateStreamAttachmentWithCallback
export type ICreateLog = (text: string) => void

export default class AttachmentManager {
  private readonly onAttachment: IAttachFunction

  constructor(onAttachment: IAttachFunction) {
    this.onAttachment = onAttachment
  }

  log(text: string): void | Promise<void> {
    return this.create(text, 'text/x.cucumber.log+plain')
  }

  create(
    data: Buffer | Readable | string,
    mediaTypeOrOptions?: string | ICreateAttachmentOptions,
    callback?: () => void
  ): void | Promise<void> {
    const options = normaliseOptions(mediaTypeOrOptions)
    if (Buffer.isBuffer(data)) {
      if (doesNotHaveValue(options.mediaType)) {
        throw Error('Buffer attachments must specify a media type')
      }
      this.createBufferAttachment(data, options.mediaType, options.fileName)
    } else if (isStream.readable(data)) {
      if (doesNotHaveValue(options.mediaType)) {
        throw Error('Stream attachments must specify a media type')
      }
      return this.createStreamAttachment(
        data,
        options.mediaType,
        options.fileName,
        callback
      )
    } else if (typeof data === 'string') {
      if (doesNotHaveValue(options.mediaType)) {
        options.mediaType = 'text/plain'
      }
      if (options.mediaType.startsWith('base64:')) {
        this.createStringAttachment(
          data,
          {
            encoding: messages.AttachmentContentEncoding.BASE64,
            contentType: options.mediaType.replace('base64:', ''),
          },
          options.fileName
        )
      } else {
        this.createStringAttachment(
          data,
          {
            encoding: messages.AttachmentContentEncoding.IDENTITY,
            contentType: options.mediaType,
          },
          options.fileName
        )
      }
    } else {
      throw Error(
        'Invalid attachment data: must be a buffer, readable stream, or string'
      )
    }
  }

  createBufferAttachment(
    data: Buffer,
    mediaType: string,
    fileName?: string
  ): void {
    this.createStringAttachment(
      data.toString('base64'),
      {
        encoding: messages.AttachmentContentEncoding.BASE64,
        contentType: mediaType,
      },
      fileName
    )
  }

  createStreamAttachment(
    data: Readable,
    mediaType: string,
    fileName?: string,
    callback?: () => void
  ): void | Promise<void> {
    const promise = new Promise<void>((resolve, reject) => {
      const buffers: Uint8Array[] = []
      data.on('data', (chunk) => {
        buffers.push(chunk)
      })
      data.on('end', () => {
        this.createBufferAttachment(Buffer.concat(buffers), mediaType, fileName)
        resolve()
      })
      data.on('error', reject)
    })
    if (doesHaveValue(callback)) {
      promise.then(callback, callback)
    } else {
      return promise
    }
  }

  createStringAttachment(
    data: string,
    media: IAttachmentMedia,
    fileName?: string
  ): void {
    this.onAttachment({
      data,
      media,
      ...(fileName ? { fileName } : {}),
    })
  }
}

function normaliseOptions(
  mediaTypeOrOptions?: string | ICreateAttachmentOptions
): Partial<ICreateAttachmentOptions> {
  if (!mediaTypeOrOptions) {
    return {}
  }
  if (typeof mediaTypeOrOptions === 'string') {
    return {
      mediaType: mediaTypeOrOptions,
    }
  }
  return mediaTypeOrOptions
}

import { create } from './stopwatch'
import UserCodeRunner from '../user_code_runner'
import * as messages from '@cucumber/messages'
import { ITestCaseHookParameter } from '../support_code_library_builder/types'
import { IDefinition, IGetInvocationDataResponse } from '../models/definition'
import {
  doesHaveValue,
  doesNotHaveValue,
  valueOrDefault,
} from '../value_checker'
import { formatError } from './format_error'

export interface IRunOptions {
  defaultTimeout: number
  filterStackTraces: boolean
  hookParameter: ITestCaseHookParameter
  step: messages.PickleStep
  stepDefinition: IDefinition
  world: any
}

export async function run({
  defaultTimeout,
  filterStackTraces,
  hookParameter,
  step,
  stepDefinition,
  world,
}: IRunOptions): Promise<messages.TestStepResult> {
  const stopwatch = create().start()
  let error: any, result: any, invocationData: IGetInvocationDataResponse

  try {
    invocationData = await stepDefinition.getInvocationParameters({
      hookParameter,
      step,
      world,
    })
  } catch (err) {
    error = err
  }

  if (doesNotHaveValue(error)) {
    const timeoutInMilliseconds = valueOrDefault(
      stepDefinition.options.timeout,
      defaultTimeout
    )

    if (invocationData.validCodeLengths.includes(stepDefinition.code.length)) {
      const data = await UserCodeRunner.run({
        argsArray: invocationData.parameters,
        fn: stepDefinition.code,
        thisArg: world,
        timeoutInMilliseconds,
      })
      error = data.error
      result = data.result
    } else {
      error = invocationData.getInvalidCodeLengthMessage()
    }
  }

  const duration = stopwatch.stop().duration()
  let status: messages.TestStepResultStatus
  let details = {}
  if (result === 'skipped') {
    status = messages.TestStepResultStatus.SKIPPED
  } else if (result === 'pending') {
    status = messages.TestStepResultStatus.PENDING
  } else if (doesHaveValue(error)) {
    details = formatError(error, filterStackTraces)
    status = messages.TestStepResultStatus.FAILED
  } else {
    status = messages.TestStepResultStatus.PASSED
  }

  return {
    duration,
    status,
    ...details,
  }
}

export default { run }

import { TestStepResult } from '@cucumber/messages'
import { format } from 'assertion-error-formatter'
import errorStackParser from 'error-stack-parser'
import { filterStackTrace } from '../filter_stack_trace'

export function formatError(
  error: Error,
  filterStackTraces: boolean
): Pick<TestStepResult, 'message' | 'exception'> {
  let filteredStack: string
  if (filterStackTraces) {
    try {
      filteredStack = filterStackTrace(errorStackParser.parse(error))
        .map((f) => f.source)
        .join('\n')
    } catch {
      // if we weren't able to parse and filter, we'll settle for the original
    }
  }
  const message = format(error, {
    colorFns: {
      errorStack: (stack: string) =>
        filteredStack ? `\n${filteredStack}` : stack,
    },
  })
  return {
    message,
    exception: {
      type: error.name || 'Error',
      message: typeof error === 'string' ? error : error.message,
    },
  }
}

